#include <algorithm>
#include <cassert>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>
using namespace std;
// 이미 정렬되면 (-1,-1), 아니면 양끝을 포함하는 최소 구간입니다.
pair<int,int> subSort(const vector<int>&v){
 const int n=static_cast<int>(v.size());if(n<2)return {-1,-1};
 int right=-1,largest=v[0];
 for(int i=1;i<n;++i){if(v[i]<largest)right=i;largest=max(largest,v[i]);}
 if(right<0)return {-1,-1};
 int left=-1,smallest=v[n-1];
 for(int i=n-2;i>=0;--i){if(v[i]>smallest)left=i;smallest=min(smallest,v[i]);}
 return {left,right};
}
pair<int,int> subSortReference(const vector<int>&v){
 if(is_sorted(v.begin(),v.end()))return {-1,-1};
 for(size_t length=1;length<=v.size();++length)for(size_t start=0;start+length<=v.size();++start){
  vector<int>w=v;sort(w.begin()+start,w.begin()+start+length);
  if(is_sorted(w.begin(),w.end()))return {static_cast<int>(start),static_cast<int>(start+length-1)};
 }
 throw logic_error("unreachable");
}
vector<string> strings(const string&alphabet,int maximum){
 vector<string>all(1,""),level(1,"");for(int n=1;n<=maximum;++n){vector<string>next;for(const string&s:level)for(char c:alphabet)next.push_back(s+c);all.insert(all.end(),next.begin(),next.end());level=next;}return all;
}
int main(){size_t cases=0;for(const string&s:strings("012",8)){vector<int>v;for(char c:s)v.push_back(c-'1');assert(subSort(v)==subSortReference(v));++cases;}assert(subSort({numeric_limits<int>::max(),numeric_limits<int>::min()})==make_pair(0,1));assert(subSort(vector<int>(100000,7))==make_pair(-1,-1));cout<<cases<<" cases\n";}
